INSERT INTO sections (id, chapter, heading, heading_path, "order", type, dm_only_text, read_aloud_text) VALUES ('creature-blue-dragon-wyrmling', 'Appendix B: Creatures', 'Blue Dragon Wyrmling', '["Creature Descriptions"]', 100000, 'creature', 'Blue Dragon Wyrmling — Medium Dragon (Chromatic), Lawful Evil.
AC 17, HP 65 (10d8 + 20), Speed walk 30 ft., burrow 15 ft., fly 60 ft..
Abilities: STR 17 (+3), DEX 10 (+0), CON 15 (+2), INT 12 (+1), WIS 11 (+0), CHA 15 (+2).
Skills: Perception +4, Stealth +2.
Immunities: Lightning.
Senses: Blindsight 10 ft., Darkvision 60 ft., Passive Perception 14.
Languages: Draconic.
Challenge: 3 (XP 700, PB +2).
Multiattack: The dragon makes two Rend attacks.
Rend: Melee Attack Roll +5, reach 5 ft. Hit: 8 (1d10 + 3) Slashing damage plus 3 (1d6) Lightning damage.
Lightning Breath (Recharge 5-6): Dexterity Saving Throw: DC 12, each creature in a 30-foot-long, 5-foot-wide Line. Failure: 21 (6d6) Lightning damage. Success: Half damage.', '');
