INSERT INTO sections (id, chapter, heading, heading_path, "order", type, dm_only_text, read_aloud_text) VALUES ('creature-salamander-fire-snake', 'Appendix B: Creatures', 'Salamander Fire Snake', '["Creature Descriptions"]', 100002, 'creature', 'Salamander Fire Snake — Medium Elemental, Neutral Evil.
AC 14, HP 27 (6d8), Speed walk 30 ft., climb 30 ft..
Abilities: STR 12 (+1), DEX 14 (+2), CON 11 (+0), INT 7 (-2), WIS 10 (+0), CHA 8 (-1).
Vulnerabilities: Cold.
Immunities: Fire.
Senses: Darkvision 60 ft., Passive Perception 10.
Languages: Understands Primordial but can''t speak.
Challenge: 1 (XP 200, PB +2).
Fire Aura: At the end of each of the salamander''s turns, each creature of the salamander''s choice in a 5-foot Emanation originating from the salamander takes 3 (1d6) Fire damage.
Bite: Melee Attack Roll +4, reach 5 ft. Hit: 6 (1d8 + 2) Piercing damage plus 3 (1d6) Fire damage.', '');
