INSERT INTO sections (id, chapter, heading, heading_path, "order", type, dm_only_text, read_aloud_text) VALUES ('creature-ghoul', 'Appendix B: Creatures', 'Ghoul', '["Creature Descriptions"]', 100004, 'creature', 'Ghoul — Medium Undead, Chaotic Evil.
AC 12, HP 22 (5d8), Speed walk 30 ft..
Abilities: STR 13 (+1), DEX 15 (+2), CON 10 (+0), INT 7 (-2), WIS 10 (+0), CHA 6 (-2).
Immunities: Poison, Charmed, Exhaustion, Poisoned.
Senses: Darkvision 60 ft., Passive Perception 10.
Languages: Common.
Challenge: 1 (XP 200, PB +2).
Multiattack: The ghoul makes two Bite attacks.
Bite: Melee Attack Roll +4, reach 5 ft. Hit: 5 (1d6 + 2) Piercing damage plus 3 (1d6) Necrotic damage.
Claw: Melee Attack Roll +4, reach 5 ft. Hit: 4 (1d4 + 2) Slashing damage. If the target isn''t Undead or elf, it is subjected to: Constitution Saving Throw DC 10. Failure: The target has the Paralyzed condition until the end of its next turn.', '');
