INSERT INTO sections (id, chapter, heading, heading_path, "order", type, dm_only_text, read_aloud_text) VALUES ('creature-harpy', 'Appendix B: Creatures', 'Harpy', '["Creature Descriptions"]', 100005, 'creature', 'Harpy — Medium Monstrosity, Chaotic Evil.
AC 11, HP 38 (7d8 + 7), Speed walk 20 ft., fly 40 ft..
Abilities: STR 12 (+1), DEX 13 (+1), CON 12 (+1), INT 7 (-2), WIS 10 (+0), CHA 13 (+1).
Senses: Passive Perception 10.
Languages: Common.
Challenge: 1 (XP 200, PB +2).
Claw: Melee Attack Roll +3, reach 5 ft. Hit: 6 (2d4 + 1) Slashing damage.
Luring Song: The harpy sings a magical melody, which lasts until the harpy''s Concentration ends on it. Wisdom Saving Throw: DC 11, each Humanoid and Giant in a 300-foot Emanation originating from the harpy when the song starts. Failure: The target has the Charmed condition until the song ends and repeats the save at the end of each of its turns. While Charmed, the target is Incapacitated and ignores the Luring Song of other harpies. If the target is more than 5 feet from the harpy, the target moves on its turn toward the harpy by the most direct route, trying to get within 5 feet of the harpy. It doesn''t avoid Opportunity Attacks; however, before moving into damaging terrain (such as lava or a pit) and whenever it takes damage from a source other than the harpy, the target repeats the save. Success: The target is immune to this harpy''s Luring Song for 24 hours.', '');
