INSERT INTO sections (id, chapter, heading, heading_path, "order", type, dm_only_text, read_aloud_text) VALUES ('creature-kobold-tinkerer', 'Appendix B: Creatures', 'Kobold Tinkerer', '["Creature Descriptions"]', 100006, 'creature', 'Kobold Tinkerer — Small Humanoid, Any Alignment.
AC 12, HP 10 (3d6), Speed walk 30 ft., fly 10 ft..
Abilities: STR 7 (-2), DEX 14 (+2), CON 10 (+0), INT 15 (+2), WIS 7 (-2), CHA 9 (-1).
Skills: Arcana +4, Perception +0.
Senses: Darkvision 60 ft., Passive Perception 10.
Languages: Common, Draconic.
Challenge: 1/4 (XP 50, PB +2).
Inquiring Mind (1/Day): The kobold can cast detect magic, requiring no components and using Intelligence as the spellcasting ability.
Pack Tactics: The kobold has Advantage on an attack roll against a creature if at least one of its allies is within 5 feet of the creature and the ally isn''t Incapacitated.
Sunlight Sensitivity: While in sunlight, the kobold has Disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight.
Dagger: Melee or Ranged Weapon Attack: +4 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 4 (1d4 + 2) piercing damage.
Alchemical Flame (Recharge 6): The kobold unleashes fire in a 15-foot cone. Each creature in that area must make a DC 12 Dexterity saving throw, taking 10 (3d6) fire damage on a failed saving throw, or half as much damage on a successful one.', '');
