INSERT INTO sections (id, chapter, heading, heading_path, "order", type, dm_only_text, read_aloud_text) VALUES ('creature-owlbear', 'Appendix B: Creatures', 'Owlbear', '["Creature Descriptions"]', 100010, 'creature', 'Owlbear — Large Monstrosity, Unaligned.
AC 13, HP 59 (7d10 + 21), Speed walk 40 ft., climb 40 ft..
Abilities: STR 20 (+5), DEX 12 (+1), CON 17 (+3), INT 3 (-4), WIS 12 (+1), CHA 7 (-2).
Skills: Perception +5.
Senses: Darkvision 60 ft., Passive Perception 15.
Languages: —.
Challenge: 3 (XP 700, PB +2).
Multiattack: The owlbear makes two Rend attacks.
Rend: Melee Attack Roll +7, reach 5 ft. Hit: 14 (2d8 + 5) Slashing damage.', '');
INSERT INTO creature_stats (section_id, stat_block_json) VALUES ('creature-owlbear', '{"name":"Owlbear","source":"MM''25 p234","size":"Large","type":"Monstrosity","alignment":"Unaligned","ac":13,"init":1,"hp_avg":59,"hp_formula":"7d10 + 21","speed":{"walk":40,"climb":40},"cr":"3","xp":700,"pb":2,"abilities":{"str":{"score":20,"mod":5,"save":5},"dex":{"score":12,"mod":1,"save":1},"con":{"score":17,"mod":3,"save":3},"int":{"score":3,"mod":-4,"save":-4},"wis":{"score":12,"mod":1,"save":1},"cha":{"score":7,"mod":-2,"save":-2}},"skills":{"Perception":5},"senses":"Darkvision 60 ft., Passive Perception 15","languages":"—","traits":[],"actions":[{"name":"Multiattack","text":"The owlbear makes two Rend attacks."},{"name":"Rend","text":"Melee Attack Roll +7, reach 5 ft. Hit: 14 (2d8 + 5) Slashing damage."}]}');
INSERT INTO sections (id, chapter, heading, heading_path, "order", type, dm_only_text, read_aloud_text) VALUES ('creature-sinensa', 'Appendix B: Creatures', 'Sinensa', '["Creature Descriptions"]', 100011, 'creature', 'Sinensa — Large Plant, Lawful Neutral.
AC 13, HP 60 (8d10 + 16), Speed walk 30 ft..
Abilities: STR 12 (+1), DEX 10 (+0), CON 14 (+2), INT 13 (+1), WIS 15 (+2), CHA 10 (+0).
Senses: Darkvision 120 ft., Passive Perception 12.
Languages: —.
Challenge: 2 (XP 450, PB +2).
Distress Spores: When Sinensa takes damage, all other myconids within 240 feet of it can sense its pain.
Sun Sickness: While in sunlight, Sinensa has Disadvantage on ability checks, attack rolls, and saving throws. Sinensa dies if it spends more than 1 hour in direct sunlight.
Multiattack: Sinensa makes one Fist attack and uses its Hallucination Spores.
Fist: Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 8 (3d4 + 1) bludgeoning damage plus 7 (2d4) poison damage.
Hallucination Spores: Sinensa ejects spores at one creature it can see within 5 feet of it. The target must succeed on a DC 12 Constitution saving throw or be poisoned for 1 minute. The poisoned target is incapacitated while it hallucinates. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.
Rapport Spores: A 30-foot radius of spores extends from Sinensa. These spores can go around corners. Affected creatures with an Intelligence score of 2 or higher that aren''t undead, constructs, or elementals can communicate telepathically with one another while within 30 feet of each other. The effect lasts for 1 hour.', '');
INSERT INTO creature_stats (section_id, stat_block_json) VALUES ('creature-sinensa', '{"name":"Sinensa","source":"DoSI p45","size":"Large","type":"Plant","alignment":"Lawful Neutral","ac":13,"ac_note":"natural armor","init":0,"hp_avg":60,"hp_formula":"8d10 + 16","speed":{"walk":30},"cr":"2","xp":450,"pb":2,"abilities":{"str":{"score":12,"mod":1,"save":1},"dex":{"score":10,"mod":0,"save":0},"con":{"score":14,"mod":2,"save":2},"int":{"score":13,"mod":1,"save":1},"wis":{"score":15,"mod":2,"save":2},"cha":{"score":10,"mod":0,"save":0}},"skills":{},"senses":"Darkvision 120 ft., Passive Perception 12","languages":"—","traits":[{"name":"Distress Spores","text":"When Sinensa takes damage, all other myconids within 240 feet of it can sense its pain."},{"name":"Sun Sickness","text":"While in sunlight, Sinensa has Disadvantage on ability checks, attack rolls, and saving throws. Sinensa dies if it spends more than 1 hour in direct sunlight."}],"actions":[{"name":"Multiattack","text":"Sinensa makes one Fist attack and uses its Hallucination Spores."},{"name":"Fist","text":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 8 (3d4 + 1) bludgeoning damage plus 7 (2d4) poison damage."},{"name":"Hallucination Spores","text":"Sinensa ejects spores at one creature it can see within 5 feet of it. The target must succeed on a DC 12 Constitution saving throw or be poisoned for 1 minute. The poisoned target is incapacitated while it hallucinates. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."},{"name":"Rapport Spores","text":"A 30-foot radius of spores extends from Sinensa. These spores can go around corners. Affected creatures with an Intelligence score of 2 or higher that aren''t undead, constructs, or elementals can communicate telepathically with one another while within 30 feet of each other. The effect lasts for 1 hour."}]}');
INSERT INTO sections (id, chapter, heading, heading_path, "order", type, dm_only_text, read_aloud_text) VALUES ('creature-runara', 'Appendix B: Creatures', 'Runara', '["Creature Descriptions"]', 100012, 'creature', 'Runara — Huge Dragon, Lawful Good.
AC 19, HP 212 (17d12 + 102), Speed walk 40 ft., fly 80 ft., swim 40 ft..
Abilities: STR 25 (+7), DEX 10 (+0), CON 23 (+6), INT 16 (+3), WIS 15 (+2), CHA 19 (+4).
Skills: Insight +7, Perception +12, Stealth +5.
Immunities: Lightning.
Senses: Blindsight 60 ft., Darkvision 120 ft., Passive Perception 22.
Languages: Common, Draconic.
Challenge: 13 (XP 10000, PB +5).
Amphibious: Runara can breathe air and water.
Legendary Resistance (3/Day): If Runara fails a saving throw, it can choose to succeed instead.
Multiattack: Runara can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws.
Bite: Melee Weapon Attack: +12 to hit, reach 10 ft., one target. Hit: 18 (2d10 + 7) piercing damage.
Claw: Melee Weapon Attack: +12 to hit, reach 5 ft., one target. Hit: 14 (2d6 + 7) slashing damage.
Frightful Presence: Each creature of Runara''s choice that is within 120 feet of Runara and aware of it must succeed on a DC 17 Wisdom saving throw or become Frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to Runara''s Frightful Presence for the next 24 hours.
Breath Weapons (Recharge 5-6): Runara uses one of the following breath weapons: Lightning Breath — exhales lightning in a 90-foot line that is 5 feet wide; each creature in that line must make a DC 19 Dexterity saving throw, taking 66 (12d10) lightning damage on a failed save, or half as much damage on a successful one. Repulsion Breath — exhales repulsion energy in a 30-foot cone; each creature in that area must succeed on a DC 19 Strength saving throw or be pushed 60 feet away from Runara.
Change Shape: Runara magically transforms into a Humanoid or Beast that is Medium or Small, while retaining her game statistics (other than her size). This transformation ends if Runara is reduced to 0 hit points or uses a bonus action to end it.', '');
