INSERT INTO sections (id, chapter, heading, heading_path, "order", type, dm_only_text, read_aloud_text) VALUES ('creature-winged-kobold', 'Appendix B: Creatures', 'Winged Kobold', '["Creature Descriptions"]', 100018, 'creature', 'Winged Kobold — Small Dragon, Neutral.
AC 15, HP 10 (4d6 - 4), Speed walk 30 ft., fly 30 ft..
Abilities: STR 7 (-2), DEX 16 (+3), CON 9 (-1), INT 8 (-1), WIS 7 (-2), CHA 8 (-1).
Senses: Darkvision 60 ft., Passive Perception 8.
Languages: Common, Draconic.
Challenge: 1/4 (XP 50, PB +2).
Pack Tactics: The kobold has Advantage on an attack roll against a creature if at least one of the kobold''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.
Sunlight Sensitivity: While in sunlight, the kobold has Disadvantage on ability checks and attack rolls.
Dragon-Tooth Blade: Melee Attack Roll +5, reach 5 ft. Hit: 6 (1d6 + 3) Piercing damage.
Chromatic Spittle: Ranged Attack Roll +5, range 30 ft. Hit: 6 (1d6 + 3) damage of a type chosen by the kobold: Acid, Cold, Fire, Lightning, or Poison.', '');
INSERT INTO creature_stats (section_id, stat_block_json) VALUES ('creature-winged-kobold', '{"name":"Winged Kobold","source":"MM''25 p185","size":"Small","type":"Dragon","alignment":"Neutral","ac":15,"init":3,"hp_avg":10,"hp_formula":"4d6 - 4","speed":{"walk":30,"fly":30},"cr":"1/4","xp":50,"pb":2,"abilities":{"str":{"score":7,"mod":-2,"save":-2},"dex":{"score":16,"mod":3,"save":3},"con":{"score":9,"mod":-1,"save":-1},"int":{"score":8,"mod":-1,"save":-1},"wis":{"score":7,"mod":-2,"save":-2},"cha":{"score":8,"mod":-1,"save":-1}},"skills":{},"senses":"Darkvision 60 ft., Passive Perception 8","languages":"Common, Draconic","traits":[{"name":"Pack Tactics","text":"The kobold has Advantage on an attack roll against a creature if at least one of the kobold''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition."},{"name":"Sunlight Sensitivity","text":"While in sunlight, the kobold has Disadvantage on ability checks and attack rolls."}],"actions":[{"name":"Dragon-Tooth Blade","text":"Melee Attack Roll +5, reach 5 ft. Hit: 6 (1d6 + 3) Piercing damage."},{"name":"Chromatic Spittle","text":"Ranged Attack Roll +5, range 30 ft. Hit: 6 (1d6 + 3) damage of a type chosen by the kobold: Acid, Cold, Fire, Lightning, or Poison."}]}');
INSERT INTO sections (id, chapter, heading, heading_path, "order", type, dm_only_text, read_aloud_text) VALUES ('creature-zombie', 'Appendix B: Creatures', 'Zombie', '["Creature Descriptions"]', 100019, 'creature', 'Zombie — Medium Undead, Neutral Evil.
AC 8, HP 15 (2d8 + 6), Speed walk 20 ft..
Abilities: STR 13 (+1), DEX 6 (-2), CON 16 (+3), INT 3 (-4), WIS 6 (-2), CHA 5 (-3).
Immunities: Poison, Exhaustion, Poisoned.
Senses: Darkvision 60 ft., Passive Perception 8.
Languages: Understands Common plus one other language but can''t speak.
Challenge: 1/4 (XP 50, PB +2).
Undead Fortitude: If damage reduces the zombie to 0 Hit Points, it makes a Constitution saving throw (DC 5 plus the damage taken) unless the damage is Radiant or from a Critical Hit. On a successful save, the zombie drops to 1 Hit Point instead.
Slam: Melee Attack Roll +3, reach 5 ft. Hit: 5 (1d8 + 1) Bludgeoning damage.', '');
INSERT INTO creature_stats (section_id, stat_block_json) VALUES ('creature-zombie', '{"name":"Zombie","source":"MM''25 p346","size":"Medium","type":"Undead","alignment":"Neutral Evil","ac":8,"init":-2,"hp_avg":15,"hp_formula":"2d8 + 6","speed":{"walk":20},"cr":"1/4","xp":50,"pb":2,"abilities":{"str":{"score":13,"mod":1,"save":1},"dex":{"score":6,"mod":-2,"save":-2},"con":{"score":16,"mod":3,"save":3},"int":{"score":3,"mod":-4,"save":-4},"wis":{"score":6,"mod":-2,"save":-2},"cha":{"score":5,"mod":-3,"save":-3}},"skills":{},"immunities":["Poison","Exhaustion","Poisoned"],"senses":"Darkvision 60 ft., Passive Perception 8","languages":"Understands Common plus one other language but can''t speak","traits":[{"name":"Undead Fortitude","text":"If damage reduces the zombie to 0 Hit Points, it makes a Constitution saving throw (DC 5 plus the damage taken) unless the damage is Radiant or from a Critical Hit. On a successful save, the zombie drops to 1 Hit Point instead."}],"actions":[{"name":"Slam","text":"Melee Attack Roll +3, reach 5 ft. Hit: 5 (1d8 + 1) Bludgeoning damage."}]}');
